package com.bank.sequence;

import java.util.*;
import java.util.logging.*;

public class IteratePredicateDemo {
    private static final Logger log = Logger.getLogger("Sequence");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        SequenceService service = new SequenceService();
        List<Integer> nums = service.oneToHundred();
        log.info(() -> "count=" + nums.size() + " first=" + nums.get(0)
            + " last=" + nums.get(nums.size() - 1));
    }
}

// ─── Would be in service/SequenceService.java ───
class SequenceService {
    List<Integer> oneToHundred() {
        return java.util.stream.Stream.iterate(
                1,                 // seed
                n -> n <= 100,     // hasNext predicate → self-terminates
                n -> n + 1)        // next function
            .toList();             // no limit needed
    }
}
